"use client"

import { useState, useEffect } from "react"
import Layout from "../components/Layout"
import EnteredVehiclesTable from "../components/EnteredVehiclesTable"
import api from "../services/api"

const EnteredVehicles = () => {
  const [enteredVehicles, setEnteredVehicles] = useState([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState("")

  useEffect(() => {
    fetchEnteredVehicles()
    const interval = setInterval(fetchEnteredVehicles, 10000)
    return () => clearInterval(interval)
  }, [])

  const fetchEnteredVehicles = async () => {
    try {
      const response = await api.get("/vehicles/all-entries")
      setEnteredVehicles(response.data)
    } catch (error) {
      console.error("Error fetching entered vehicles:", error)
    } finally {
      setLoading(false)
    }
  }

  const filteredVehicles = enteredVehicles.filter(
    (vehicle) =>
      typeof vehicle.licensePlate === "string" &&
      vehicle.licensePlate.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const exportData = () => {
    const csvContent =
      "data:text/csv;charset=utf-8," +
      "License Plate,Entry Time,Vehicle Type,Camera ID,Status,Confidence\n" +
      filteredVehicles
        .map((vehicle) =>
          `${vehicle.licensePlate},${new Date(vehicle.entryTime).toLocaleString()},${vehicle.vehicleType},${vehicle.cameraId},${vehicle.status},${vehicle.confidence || "N/A"}`
        )
        .join("\n")

    const encodedUri = encodeURI(csvContent)
    const link = document.createElement("a")
    link.setAttribute("href", encodedUri)
    link.setAttribute("download", "entered_vehicles.csv")
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
  }

  return (
    <Layout>
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Entered Vehicles</h1>
            <p className="text-gray-600">All vehicles that have entered the parking system</p>
          </div>
          <div className="flex space-x-3">
            <button
              onClick={fetchEnteredVehicles}
              disabled={loading}
              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50"
            >
              {loading ? "Refreshing..." : "Refresh"}
            </button>
            <button onClick={exportData} className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700">
              Export CSV
            </button>
          </div>
        </div>

        <div className="bg-white p-4 rounded-lg shadow">
          <input
            type="text"
            placeholder="Search by license plate..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-blue-500 focus:border-blue-500"
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <StatCard
            icon="📥"
            label="Total Entries"
            value={enteredVehicles.length}
            bg="bg-blue-100"
          />
          <StatCard
            icon="🚗"
            label="Currently Parked"
            value={enteredVehicles.filter((v) => v.status === "parked").length}
            bg="bg-green-100"
          />
          <StatCard
            icon="🚪"
            label="Already Exited"
            value={enteredVehicles.filter((v) => v.status === "exited").length}
            bg="bg-gray-100"
          />
        </div>

        <EnteredVehiclesTable vehicles={filteredVehicles} loading={loading} />
      </div>
    </Layout>
  )
}

const StatCard = ({ icon, label, value, bg }) => (
  <div className="bg-white p-4 rounded-lg shadow">
    <div className="flex items-center">
      <div className={`p-2 ${bg} rounded-lg`}>
        <span className="text-2xl">{icon}</span>
      </div>
      <div className="ml-4">
        <p className="text-sm font-medium text-gray-600">{label}</p>
        <p className="text-2xl font-bold text-gray-900">{value}</p>
      </div>
    </div>
  </div>
)

export default EnteredVehicles
